    "Website SEO data (free: Open PageRank)": "Datos SEO del sitio (gratis: Open PageRank)",
    "Free: get a key at openpagerank.keywordseverywhere.com/dashboard (sign in with a Keywords Everywhere key; old DomCop keys no longer work). It gives a 0-10 authority score and the world rank of a lead website. Used when no Ahrefs or Ubersuggest key answers. The basic SEO checks (title, description, mobile, indexing, robots.txt, sitemap) need no key at all.": "Gratis: consigue una clave en openpagerank.keywordseverywhere.com/dashboard (basta una cuenta). Da una nota de autoridad de 0 a 10 y el ranking mundial del sitio de un lead. Se usa si ninguna clave de Ahrefs o Ubersuggest responde. Las comprobaciones SEO básicas (título, descripción, móvil, indexación, robots.txt, sitemap) no necesitan ninguna clave.",
    "Open PageRank API key": "Clave API de Open PageRank",
    "World rank": "Ranking mundial",
    "SEO basics": "SEO básico",
    "SEO figures (authority, traffic, keywords, backlinks) appear here once an Ahrefs, Ubersuggest or free Open PageRank key is saved in Settings → AI.": "Las cifras SEO (autoridad, tráfico, palabras clave, backlinks) aparecen aquí cuando se guarda una clave de Ahrefs, Ubersuggest o Open PageRank (gratis) en Ajustes → IA.",
    "Website SEO data (Ahrefs)": "Datos SEO del sitio web (Ahrefs)",
    "With your Ahrefs API key (API v3), hovering the website of a lead shows its domain rating, organic traffic and keywords, and backlinks. When both keys are saved, Ahrefs is used. The key is stored encrypted and never shown again.": "Con tu clave API de Ahrefs (API v3), al pasar el ratón por el sitio web de un lead verás su Domain Rating, tráfico y palabras clave orgánicas, y backlinks. Si hay ambas claves, se usa Ahrefs. La clave se guarda cifrada y no se vuelve a mostrar.",
    "Ahrefs API key": "Clave API de Ahrefs",
    "SEO figures (authority, traffic, keywords, backlinks) appear here once an Ahrefs or Ubersuggest key is saved in Settings → AI.": "Las cifras SEO (autoridad, tráfico, palabras clave, backlinks) aparecen aquí cuando se guarda una clave de Ahrefs o Ubersuggest en Ajustes → IA.",
