    "The same notifications as by email, as a short message with the link. Your administrator sets up the accounts in Settings.": "Las mismas notificaciones que por correo, como mensaje corto con el enlace. Su administrador configura las cuentas en Ajustes.",
    "WhatsApp and Telegram": "WhatsApp y Telegram",
    "WhatsApp number": "Número de WhatsApp",
    "WhatsApp & Telegram": "WhatsApp y Telegram",
    "Send notifications by WhatsApp and Telegram, next to email": "Enviar notificaciones por WhatsApp y Telegram, además del correo",
    "Create a bot with @BotFather and paste its token. Each person then sends /start to the bot and enters their chat id (for example from @userinfobot) in their profile.": "Cree un bot con @BotFather y pegue su token. Cada persona envía /start al bot y escribe su chat id (por ejemplo desde @userinfobot) en su perfil.",
    "Send notifications by Telegram": "Enviar notificaciones por Telegram",
    "Bot token": "Token del bot",
    "WhatsApp (Cloud API)": "WhatsApp (Cloud API)",
    "From Meta for Developers → WhatsApp → API setup: the phone number ID and a permanent access token. Outside a 24 hour conversation WhatsApp only delivers approved templates: give the name of a template with one body variable and its language, or leave it empty for plain messages.": "Desde Meta for Developers → WhatsApp → Configuración de la API: el ID del número de teléfono y un token de acceso permanente. Fuera de una conversación de 24 h WhatsApp solo entrega plantillas aprobadas: indique el nombre de una plantilla con una variable de cuerpo y su idioma, o déjelo vacío para mensajes simples.",
