    "Name, email, phone, company, website, city and message are recognised in English, French, Spanish and Arabic. Add your own labels only if a field is missed. Anything not recognised is kept in the lead's description.": "Nombre, correo, teléfono, empresa, sitio web, ciudad y mensaje se reconocen en inglés, francés, español y árabe. Añade tus propias etiquetas solo si se pierde un campo. Lo que no se reconoce se guarda en la descripción del lead.",
