    "Only emails that match every filter you fill in become leads. Everything else stays untouched in the mailbox. Separate several words with commas.": "Solo los correos que cumplen todos los filtros rellenados se convierten en leads. Todo lo demás queda intacto en el buzón. Separa varias palabras con comas.",
