    "Open lead": "Abrir lead",
    "Pick the source, status and the person who follows up, then use Preview to see how the latest emails would be read.": "Elige la fuente, el estado y la persona que hace el seguimiento; luego usa Vista previa para ver cómo se leerían los últimos correos.",
