    "The emails this client's contacts receive from us. Switch one off to stop those emails for all its contacts (they stay available in the client area).": "Los correos que reciben de nosotros los contactos de este cliente. Desactiva un tipo para detenerlos para todos sus contactos (siguen disponibles en el área de cliente).",
    "Tasks shared with the client": "Tareas compartidas con el cliente",
    "The client sees this task in its client area (Tasks): status, dates, description, progress, the files you share and the comments you send to it. It can write and add files.": "El cliente ve esta tarea en su área (Tareas): estado, fechas, descripción, progreso, los archivos que compartes y los comentarios que le envías. Puede escribir y añadir archivos.",
    "A lead has no client area yet: the task becomes visible to the client once the lead is converted.": "Un lead aún no tiene área de cliente: la tarea será visible para el cliente cuando se convierta.",
    "Link the task to the client, to one of its projects or to its lead (Related to), otherwise nobody can see it.": "Vincula la tarea al cliente, a uno de sus proyectos o a su lead (Relacionado con); si no, nadie podrá verla.",
