    "No backup yet.": "Aún no hay copias.",
    "There is no backup yet.": "Todavía no hay ninguna copia.",
    "The file storage (DigitalOcean Spaces) is not set up, so there is nowhere to put the backups.": "El almacenamiento de archivos (DigitalOcean Spaces) no está configurado: no hay dónde guardar las copias.",
    "The last good backup is older than a day and a half.": "La última copia correcta tiene más de día y medio.",
    "To restore a file, download it and run: node scripts/restore-backup.mjs <file> (add --apply to write).": "Para restaurar un archivo, descárgalo y ejecuta: node scripts/restore-backup.mjs <archivo> (añade --apply para escribir).",
    "Your administrator requires two-step sign-in. Turn on the authenticator app or the email code below to keep using the CRM.": "Tu administrador exige el inicio de sesión en dos pasos. Activa la app de autenticación o el código por email para seguir usando el CRM.",
    "Your administrator requires two-step sign-in: turn it on in your profile, Security, to continue.": "Tu administrador exige el inicio de sesión en dos pasos: actívalo en tu perfil, Seguridad, para continuar.",
    "Two-step sign-in": "Inicio de sesión en dos pasos",
    "Required for": "Obligatorio para",
    "Nobody (optional for everyone)": "Nadie (opcional para todos)",
    "Administrators and people who see the vault, payments or payroll": "Administradores y personas que ven la bóveda, los pagos o la nómina",
    "Make the second step (authenticator app or email code) compulsory. Someone the rule covers who has not turned it on can only open their profile, Security, until they do. Everybody can always turn it on themselves.": "Haz obligatorio el segundo paso (app de autenticación o código por email). Quien esté cubierto y no lo haya activado solo puede abrir su perfil, Seguridad, hasta hacerlo. Cualquiera puede activarlo por sí mismo.",
    "Backups": "Copias de seguridad",
    "Backup files": "Archivos de copia",
    "Back up the database every night": "Copiar la base de datos cada noche",
    "Every night after 02:00 (company time) the whole database is saved to the file storage: the last 14 days and one a week for 12 weeks. It does not need the automatic tasks to be on.": "Cada noche después de las 02:00 (hora de la empresa) toda la base de datos se guarda en el almacenamiento de archivos: los últimos 14 días y una por semana durante 12 semanas. No requiere que las tareas automáticas estén activadas.",
    "Alerts": "Alertas",
    "Send alerts to the administrators": "Enviar alertas a los administradores",
    "The administrators are told (bell, email, Telegram / WhatsApp) when a backup fails or is late, when the automatic tasks stop or report errors, and when the CRM returns a burst of server errors. The same alert is sent once an hour at most.": "Los administradores reciben aviso (campana, email, Telegram / WhatsApp) cuando una copia falla o se retrasa, cuando las tareas automáticas se detienen o dan errores, y cuando el CRM devuelve una ráfaga de errores del servidor. La misma alerta se envía como máximo una vez por hora.",
