    "Weekly schedule: who takes meetings, which days and hours": "Horario semanal: quién atiende las reuniones, qué días y horas",
    "Tick the days people can book, set the hours of each day (10-13,14-17 = 10:00 to 13:00 and 14:00 to 17:00, 24-hour clock) and choose the team members who take the meetings that day. A visitor is offered a time only when at least one of them is free, and the meeting is given to the one who is free. No one chosen = the team members below.": "Marca los días reservables, define las horas de cada día (10-13,14-17 = de 10:00 a 13:00 y de 14:00 a 17:00, reloj de 24 h) y elige los miembros que atienden las reuniones ese día. Solo se ofrece una hora si al menos uno está libre, y la reunión se asigna al que esté libre. Nadie elegido = el equipo de abajo.",
    "Default team for the meetings": "Equipo por defecto para las reuniones",
    "Used for a day with nobody chosen in the weekly schedule. They are told about each request and can accept or refuse it. Empty = every administrator.": "Se usa para un día sin nadie elegido en el horario semanal. Se les avisa de cada solicitud y pueden aceptarla o rechazarla. Vacío = todos los administradores.",
