    "Reply to": "Responder a",
    "Add Cc, Bcc or Reply to": "Añadir Cc, Cco o Responder a",
    "Several addresses can be separated by commas. The date becomes the sending time when you send.": "Varias direcciones pueden separarse con comas. La fecha pasa a ser la hora de envío al enviar.",
    "Up to 10 MB per file, 20 MB in all.": "Hasta 10 MB por archivo, 20 MB en total.",
    "Save the draft first, then you can attach files.": "Guarde primero el borrador y luego podrá adjuntar archivos.",
    "Choose the address to send from in the list": "Elija en la lista la dirección desde la que enviar",
    "The attached files are larger than 20 MB together": "Los archivos adjuntos superan los 20 MB en total",
    "Other \"send from\" addresses (lead mails)": "Otras direcciones de envío (correos de leads)",
    "Addresses a lead mail can be sent from, besides the mail server address and the staff member's own email. Your mail server must allow them. Separate several with commas.": "Direcciones desde las que se puede enviar un correo de lead, además de la del servidor de correo y el correo del propio empleado. Su servidor de correo debe permitirlas. Sepárelas con comas.",
    "Note for whoever sends it": "Nota para quien lo envía",
    "What to do, change or check before sending (not sent to the lead)": "Qué hacer, cambiar o comprobar antes de enviar (no se envía al lead)",
    "Checks to confirm before sending": "Comprobaciones a confirmar antes de enviar",
    "Add a check, then press Enter": "Añada una comprobación y pulse Enter",
    "Confirm the red checks first": "Confirme primero las comprobaciones en rojo",
    "Confirm every check before sending": "Confirme cada comprobación antes de enviar",
    "Check not found": "Comprobación no encontrada",
    "Pipeline and team": "Pipeline y equipo",
    "Expand all": "Expandir todo",
    "Collapse all": "Contraer todo",
    "Addresses a lead mail can be sent from, besides hello@trtmaroc.com (always first, the default) and the staff member's own email. Your mail server must allow them. Separate several with commas.": "Direcciones desde las que se puede enviar un correo de lead, además de hello@trtmaroc.com (siempre la primera, por defecto) y el correo del propio empleado. Su servidor de correo debe permitirlas. Sepárelas con comas.",
    "Billing and options": "Facturación y opciones",
    "Replying to": "Respondiendo a",
    "You": "Usted",
    "Voice message": "Mensaje de voz",
    "Open in new tab": "Abrir en una pestaña nueva",
    "Send-from accounts": "Cuentas de envío",
    "Some mail servers only accept a sender that is the account used to log in. Give each address you send from (for example hello@trtmaroc.com) its own login here; the CRM uses it when that address is chosen as the sender of a lead mail. Leave the server empty to use the one above.": "Algunos servidores de correo solo aceptan un remitente igual a la cuenta de acceso. Dé aquí a cada dirección de envío (por ejemplo hello@trtmaroc.com) su propio acceso; el CRM lo usa cuando esa dirección se elige como remitente de un correo de lead. Deje el servidor vacío para usar el de arriba.",
    "Same as the sender email": "Igual que el correo del remitente",
    "Use another mail server for this address": "Usar otro servidor de correo para esta dirección",
    "No send-from account yet.": "Aún no hay cuentas de envío.",
    "Add an account": "Añadir una cuenta",
    "Save accounts": "Guardar cuentas",
    "Send-from accounts saved": "Cuentas de envío guardadas",
    "Save first, then test. The passwords are stored on the server and never shown again.": "Guarde primero y luego pruebe. Las contraseñas se guardan en el servidor y no se vuelven a mostrar.",
    "See every event, private ones included": "Ver todos los eventos, incluidos los privados",
    "Edit and delete events of others": "Editar y eliminar eventos de otros",
    "Anyone who can open the Calendar adds events": "Quien pueda abrir el calendario añade eventos",
    "Everyone edits their own events": "Cada uno edita sus propios eventos",
    "Everyone deletes their own events": "Cada uno elimina sus propios eventos",
    "Send it automatically at a chosen date and time": "Enviarlo automáticamente en la fecha y hora elegidas",
    "It is sent at the first run of the automatic tasks after that time, from the address chosen above. Every check must be confirmed first.": "Se envía en la primera ejecución de las tareas automáticas tras esa hora, desde la dirección elegida arriba. Primero hay que confirmar todas las comprobaciones.",
    "Scheduled for": "Programado para",
    "Not sent automatically": "No enviado automáticamente",
    "The text changed, so the checks and the schedule were cancelled. Confirm the checks, then schedule it again.": "El texto cambió, así que se cancelaron las comprobaciones y la programación. Confirme las comprobaciones y vuelva a programarlo.",
    "Scheduled lead mails": "Correos de leads programados",
    "Sends the lead mail drafts that have a date and time to send automatically (Lead popup → Mails). A draft goes out at the first run after its time, so the automatic tasks must run often (for example every 5 minutes).": "Envía los borradores de correo de leads que tienen fecha y hora de envío automático (ventana del lead → Correos). Un borrador sale en la primera ejecución tras su hora, así que las tareas automáticas deben ejecutarse a menudo (por ejemplo cada 5 minutos).",
    "Send the scheduled lead mails": "Enviar los correos de leads programados",
    "Choose a date and time in the future to send the mail": "Elija una fecha y hora futuras para el envío",
    "Add the email address to send to before scheduling": "Añada la dirección del destinatario antes de programar",
    "Write a subject before scheduling": "Escriba un asunto antes de programar",
    "Confirm every check before scheduling": "Confirme cada comprobación antes de programar",
    "The date to send the mail is not valid": "La fecha de envío no es válida",
    "Send automatically": "Envío automático",
    "Remind me": "Recordármelo",
    "You are told on the bell, by email and on Telegram or WhatsApp (if set in your profile) at the first run of the automatic tasks after that time. Only you see this note.": "Se le avisa en la campana, por correo y por Telegram o WhatsApp (si lo configuró en su perfil) en la primera ejecución de las tareas automáticas tras esa hora. Solo usted ve esta nota.",
    "Note and ticket reminders": "Recordatorios de notas",
    "A note with \"Remind me at\" tells its owner on the bell, by email and on Telegram / WhatsApp (if set in their profile) at the first run after that time, so the automatic tasks must run often (for example every 5 minutes).": "Una nota con «Recordármelo» avisa a su dueño en la campana, por correo y por Telegram / WhatsApp (si lo configuró en su perfil) en la primera ejecución tras esa hora, así que las tareas automáticas deben ejecutarse a menudo (por ejemplo cada 5 minutos).",
    "Send the note reminders": "Enviar los recordatorios de notas",
    "Remind me at": "Recordármelo a las",
