    "automatic message": "mensaje automático",
    "No task for this ticket yet.": "Aún no hay tareas para este ticket.",
    "My reminders": "Mis recordatorios",
    "No reminder on this ticket.": "Sin recordatorios en este ticket.",
    "Client satisfaction": "Satisfacción del cliente",
