    "Only you are told: on the bell, by email and on Telegram or WhatsApp (if set in your profile) at the first run of the automatic tasks after that time.": "Solo usted recibe el aviso: en la campana, por correo y por Telegram o WhatsApp (si lo configuró en su perfil) en la primera ejecución de las tareas automáticas tras esa hora.",
    "Note (optional)": "Nota (opcional)",
