    "Automatic messages": "Mensajes automáticos",
    "When a ticket gets a status, the client receives the message you write here, in the conversation and/or by email. Use the fields to personalise it.": "Cuando un ticket pasa a un estado, el cliente recibe el mensaje que escriba aquí, en la conversación y/o por correo. Use los campos para personalizarlo.",
