    "API and webhooks": "API y webhooks",
    "Two ways to talk to the CRM from outside, both secure: keys to read and push data, webhooks to be told when something happens.": "Dos formas de hablar con el CRM desde fuera, ambas seguras: claves para leer y enviar datos, webhooks para que le avisen cuando algo ocurre.",
    "API keys": "Claves API",
    "Webhooks": "Webhooks",
    "How to use": "Cómo usar",
    "New API key": "Nueva clave API",
    "An API key lets another program (a website form, n8n, Zapier, your own code) read or push data. Give each program its own key with only what it needs, and revoke it when it is not used any more.": "Una clave API permite a otro programa (un formulario web, n8n, Zapier, su código) leer o enviar datos. Dé a cada programa su propia clave con solo lo que necesita y revóquela cuando ya no se use.",
