    "Nothing can be deleted through the API. Passwords, bank details and private notes are never available.": "Nada se puede eliminar mediante la API. Las contraseñas, datos bancarios y notas privadas nunca están disponibles.",
    "Expires on (optional)": "Caduca el (opcional)",
    "Create the key": "Crear la clave",
    "Your new API key": "Su nueva clave API",
    "Copy it now. It is shown only once and cannot be shown again: if you lose it, revoke it and create another.": "Cópiela ahora. Solo se muestra una vez: si la pierde, revóquela y cree otra.",
