    "The program that uses \"{name}\" stops working at once. This cannot be undone.": "El programa que usa «{name}» deja de funcionar al instante. No se puede deshacer.",
    "A webhook is the other direction: when something happens in the CRM (a lead arrives, a task is created…) the CRM calls the address you give, with the data, signed so that your program can check it really comes from here.": "Un webhook va en el otro sentido: cuando algo ocurre en el CRM (llega un lead, se crea una tarea…) el CRM llama a la dirección que usted indique, con los datos, firmados para que su programa compruebe que vienen de aquí.",
