    "Copy it now, it is shown only once. Your program uses it to check the signature of every call.": "Cópielo ahora, solo se muestra una vez. Su programa lo usa para comprobar la firma de cada llamada.",
    "Delete this webhook?": "¿Eliminar este webhook?",
    "Webhook deleted": "Webhook eliminado",
    "Send your key": "Envíe su clave",
    "Every call carries the key in a header. Answers are JSON. Limit: 120 calls a minute per key.": "Cada llamada lleva la clave en una cabecera. Las respuestas son JSON. Límite: 120 llamadas por minuto y clave.",
    "Resources": "Recursos",
    "Resource": "Recurso",
    "Create / change": "Crear / cambiar",
    "Lists take ?limit= (up to 100), ?page=, ?q= (search) and ?updated_since= (ISO date), and answer { data, page, limit, total }.": "Las listas aceptan ?limit= (hasta 100), ?page=, ?q= (búsqueda) y ?updated_since= (fecha ISO), y responden { data, page, limit, total }.",
    "Push a lead (for example from a website form)": "Enviar un lead (por ejemplo desde un formulario web)",
    "Push an idea to the Grow board": "Enviar una idea al tablero Grow",
    "Check a webhook call": "Comprobar una llamada de webhook",
    "Each call has the headers X-TRT-Event and X-TRT-Signature (t=<seconds>,v1=<hmac>). Recompute the HMAC SHA-256 of \"<t>.<raw body>\" with your signing secret and compare. Refuse calls whose t is older than 5 minutes.": "Cada llamada lleva las cabeceras X-TRT-Event y X-TRT-Signature (t=<segundos>,v1=<hmac>). Recalcule el HMAC SHA-256 de «<t>.<cuerpo sin procesar>» con su secreto y compare. Rechace las llamadas cuyo t tenga más de 5 minutos.",
