    "Client secret": "Secreto de cliente",
    "Copy the secret now. It is shown only once: if you lose it, create a new one.": "Copie el secreto ahora. Solo se muestra una vez: si lo pierde, cree uno nuevo.",
    "Delete this app?": "¿Eliminar esta aplicación?",
    "Let another app of yours (the Meet app) sign the team in with their CRM account. Only active team members can sign in: clients never. Guests of a meeting use the meeting link and are admitted by a team member.": "Deje que otra de sus aplicaciones (Meet) inicie sesión al equipo con su cuenta del CRM. Solo pueden entrar miembros activos del equipo: nunca los clientes. Los invitados de una reunión usan el enlace y los admite un miembro del equipo.",
    "New secret": "Nuevo secreto",
    "No app yet.": "Aún no hay aplicaciones.",
    "Redirect addresses (one per line): where the app receives the sign-in": "Direcciones de redirección (una por línea): donde la aplicación recibe el inicio de sesión",
    "Sign in with CRM": "Iniciar sesión con el CRM",
    "Sign-out addresses (optional, one per line)": "Direcciones de cierre de sesión (opcional, una por línea)",
    "Ways to talk to the CRM from outside, all secure: keys to read and push data, webhooks to be told when something happens, and sign-in for your other apps.": "Formas seguras de hablar con el CRM desde fuera: claves para leer y enviar datos, webhooks para que le avisen y el inicio de sesión para sus otras aplicaciones.",
    "What the app learns about the person: id, name, email, photo, staff id, whether they are an administrator and their role. Any OpenID Connect library works with the discovery address.": "Lo que la aplicación sabe de la persona: id, nombre, correo, foto, id del miembro, si es administradora y su rol. Cualquier biblioteca OpenID Connect funciona con la dirección de descubrimiento.",
