    "First time, at": "Primera vez, el",
    "Good morning team, the weekly meeting is at 10:00 on meet.trtcrm.com/internal": "Buenos días equipo, la reunión semanal es a las 10:00 en meet.trtcrm.com/internal",
    "It goes out at the first run of the automatic tasks after that time (Settings → Cron job), so they must run often, for example every 5 minutes.": "Sale en la primera ejecución de las tareas automáticas después de esa hora (Ajustes → Cron job), por lo que deben ejecutarse a menudo, por ejemplo cada 5 minutos.",
    "Message deleted": "Mensaje eliminado",
    "Message saved": "Mensaje guardado",
    "Messages the CRM posts in the team chat by itself at the date and time you choose, once or repeating: announcements, rules, reminders, the weekly meeting. They appear as sent by you.": "Mensajes que el CRM publica solo en el chat del equipo en la fecha y hora elegidas, una vez o repetidos: anuncios, normas, recordatorios, la reunión semanal. Aparecen como enviados por usted.",
