    "Make a task of it": "Convertir en tarea",
    "Measure": "Medida",
    "No AI key yet. Add one in Settings → AI, then come back.": "Aún no hay clave de IA. Añada una en Ajustes → IA y vuelva.",
    "No idea for this client yet. Write one, or let the AI study the client and its competitors and suggest what is worth proposing.": "Aún no hay ideas para este cliente. Escriba una, o deje que la IA estudie al cliente y a sus competidores y sugiera lo que vale la pena proponer.",
    "No message yet": "Aún no hay mensajes",
    "Nothing goes to the client: you pick the ideas and they become drafts.": "Nada llega al cliente: usted elige las ideas y pasan a borradores.",
    "Only the team can see it": "Solo el equipo puede verla",
    "Our opening": "Nuestra oportunidad",
    "Our service": "Nuestro servicio",
    "Price": "Precio",
    "Price (optional)": "Precio (opcional)",
    "Proposes only ideas we can deliver with our services and prices, each with its evidence, plan, gain and effort.": "Solo propone ideas que podemos entregar con nuestros servicios y precios, cada una con su evidencia, plan, ganancia y esfuerzo.",
    "Questions and answers between you and the client appear here.": "Las preguntas y respuestas entre usted y el cliente aparecen aquí.",
    "Reads what we sold this client, its projects, support subjects, proposals and the ideas already written.": "Lee lo que vendimos a este cliente, sus proyectos, asuntos de soporte, propuestas y las ideas ya escritas.",
    "Research": "Investigar",
    "Researching… this can take up to two minutes when the AI searches the web.": "Investigando… puede tardar hasta dos minutos cuando la IA busca en la web.",
    "Saved. {n} email(s) sent to the client.": "Guardado. {n} correo(s) enviado(s) al cliente.",
    "Saving with the status Proposed shows the idea in the client area and emails the client's contacts.": "Guardar con el estado Propuesta muestra la idea en el área de cliente y envía un correo a los contactos del cliente.",
    "Search again": "Buscar de nuevo",
    "Search the web (competitors, market, what is new)": "Buscar en la web (competidores, mercado, novedades)",
    "Searches the web for its business and its closest competitors, and compares them with the client.": "Busca en la web su negocio y a sus competidores más cercanos y los compara con el cliente.",
    "Sent to {ai}: the company name, website and industry, what we invoiced and sold, project and support subjects. No contact names, emails or phone numbers.": "Enviado a {ai}: el nombre de la empresa, su web y sector, lo que facturamos y vendimos, asuntos de proyectos y soporte. Ningún nombre de contacto, correo ni teléfono.",
    "Sources found by the AI": "Fuentes encontradas por la IA",
    "Status and client": "Estado y cliente",
    "Team and work": "Equipo y trabajo",
    "Team only": "Solo el equipo",
    "The AI found nothing worth proposing. Add more context and try again.": "La IA no encontró nada que valga la pena proponer. Añada más contexto e inténtelo de nuevo.",
    "The business": "El negocio",
    "The client can see it": "El cliente puede verla",
    "The client was emailed ({n})": "Se envió un correo al cliente ({n})",
    "The idea": "La idea",
    "The idea and its messages are removed. The client will not see it any more.": "La idea y sus mensajes se eliminan. El cliente ya no la verá.",
    "The task already exists": "La tarea ya existe",
    "The task is linked to this client and given to the people above.": "La tarea se vincula a este cliente y se asigna a las personas de arriba.",
    "They do well": "Lo que hacen bien",
    "What the client gains": "Lo que gana el cliente",
    "What the helper does": "Qué hace el asistente",
    "What we propose, in one line": "Lo que proponemos, en una línea",
    "Who works on it": "Quién trabaja en ello",
    "Why": "Por qué",
    "Why it matters for this client, the steps, what we do and what they do": "Por qué importa a este cliente, los pasos, qué hacemos nosotros y qué hacen ellos",
    "Write to the client…": "Escribir al cliente…",
    "ideas": "ideas",
    "seo, ads, site (separated by commas)": "seo, anuncios, web (separados por comas)",
    "waiting for the client": "esperando al cliente",
