    "No items match": "Ningún artículo coincide",
    "No items yet. Add one, or let the AI help write some.": "Aún no hay artículos. Añada uno o deje que la IA redacte algunos.",
    "No key saved yet": "Aún no hay clave guardada",
    "Open the website in a new tab": "Abrir el sitio en una pestaña nueva",
    "Prices are suggestions: check them before you use them.": "Los precios son sugerencias: compruébelos antes de usarlos.",
    "Rename or recolour": "Renombrar o cambiar de color",
    "Rename or recolour the group": "Renombrar o cambiar el color del grupo",
    "SEO figures": "Datos SEO",
    "SEO figures (authority, traffic, keywords, backlinks) appear here once an Ubersuggest key is saved in Settings → AI.": "Los datos SEO (autoridad, tráfico, palabras clave, backlinks) aparecen aquí cuando se guarda una clave de Ubersuggest en Ajustes → IA.",
    "Say what you sell. The AI proposes items with a description, a unit and a price; you choose the ones to add.": "Diga lo que vende. La IA propone artículos con descripción, unidad y precio; usted elige los que añadir.",
    "Search items": "Buscar artículos",
    "The products and services you add to proposals, estimates and invoices": "Los productos y servicios que añade a propuestas, presupuestos y facturas",
    "Ubersuggest API key": "Clave API de Ubersuggest",
    "Website SEO data (Ubersuggest)": "Datos SEO del sitio (Ubersuggest)",
    "With your Ubersuggest API key, hovering the website of a lead also shows its domain authority, organic traffic and keywords, and backlinks. The key is stored encrypted and never shown again.": "Con su clave API de Ubersuggest, al pasar el cursor sobre el sitio web de un lead también se muestra su autoridad de dominio, tráfico y palabras clave orgánicas, y backlinks. La clave se guarda cifrada y no se vuelve a mostrar.",
